<?php $pageTitle='Certificados';$pageSubtitle='Consulta y visualiza los certificados que has obtenido.';require __DIR__.'/../partials/header.php'; ?><div class="grid"><?php foreach($certificados as $x): ?><div class="certificate"><h2>Certificado de finalización</h2><p>Se certifica que</p><h2><?=htmlspecialchars($x['nombre'].' '.$x['apellido'])?></h2><p>ha completado satisfactoriamente</p><h3><?=htmlspecialchars($x['titulo_curso'])?></h3><p>Fecha de emisión: <?=date('d/m/Y',strtotime($x['fecha_emision']))?></p><p class="code"><?=htmlspecialchars($x['codigo_validacion'])?></p><a class="btn btn-primary" href="index.php?route=certificado&id=<?=$x['id_certificado']?>">Ver certificado</a></div><?php endforeach; ?><?php if(!$certificados): ?><div class="empty">Aún no tienes certificados.</div><?php endif; ?></div><?php require __DIR__.'/../partials/footer.php'; ?>
